// Convierte cualquier mensaje de WhatsApp en un formato simple y único.
// Ignora los eventos de estado (enviado, entregado, leído).
// Ignora mensajes viejos (reenvíos tardíos de Meta):
//   - taps de botones/listas y audios: más de 10 minutos
//   - textos y otros: más de 1 hora
const MAX_EDAD_OPCION = 10 * 60;
const MAX_EDAD_TEXTO = 60 * 60;
const ahora = Math.floor(Date.now() / 1000);
const salida = [];

for (const item of $input.all()) {
  const raw = item.json;
  // Soporta el formato del trigger y el payload completo de Meta
  const value = raw.entry?.[0]?.changes?.[0]?.value ?? raw;

  const m = value.messages?.[0];
  if (!m) continue;

  let tipo = 'otro';
  let texto = '';
  let respuesta_id = null;
  let audio_id = null;

  if (m.type === 'text') {
    tipo = 'texto';
    texto = (m.text?.body ?? '').trim();
  } else if (m.type === 'interactive') {
    // Respuesta a botones o a listas
    const r = m.interactive?.button_reply ?? m.interactive?.list_reply;
    tipo = 'opcion';
    respuesta_id = r?.id ?? null;
    texto = r?.title ?? '';
  } else if (m.type === 'button') {
    // Botón de una plantilla (recordatorio, seguimientos)
    tipo = 'opcion';
    respuesta_id = m.button?.payload ?? null;
    texto = m.button?.text ?? '';
  } else if (m.type === 'audio') {
    // Nota de voz: se transcribe más adelante
    tipo = 'audio';
    audio_id = m.audio?.id ?? null;
  }

  // Hora original del mensaje (segundos). Si no viene, no se filtra.
  const enviado = Number(m.timestamp);
  const edad_seg = Number.isFinite(enviado) ? ahora - enviado : 0;

  // Mensaje viejo: responde a algo que ya pasó, se descarta.
  const limite = (tipo === 'opcion' || tipo === 'audio') ? MAX_EDAD_OPCION : MAX_EDAD_TEXTO;
  if (edad_seg > limite) continue;

  salida.push({
    json: {
      phone_number_id: value.metadata?.phone_number_id,
      telefono: m.from,
      nombre_perfil: value.contacts?.[0]?.profile?.name ?? null,
      mensaje_id: m.id,
      tipo,
      texto,
      respuesta_id,
      audio_id,
      edad_seg,
    },
  });
}

return salida;

// ROUTER: decide qué hacer según el paso de la conversación
// y lo que respondió el cliente. No envía nada, solo decide.
const ctx = $('Contexto').first().json;          // contexto de la conversación
const msgBase = $('Normalizar').first().json;    // mensaje del cliente

// Si llegó un audio, se usa la opción que eligió "Interpretar audio"
const audio = $('Interpretar audio').isExecuted ? $('Interpretar audio').first().json : null;
const msg = audio
  ? { ...msgBase, respuesta_id: audio.respuesta_id, texto: audio.texto, tipo: audio.respuesta_id ? 'opcion' : 'audio' }
  : msgBase;

const phone = msg.phone_number_id;
const tel = msg.telefono;
const id = msg.respuesta_id ?? '';
const textoPlano = (msg.texto ?? '').toLowerCase().trim();
const tz = ctx.zona_horaria || 'America/Bogota';

let datos = { ...(ctx.datos ?? {}) };
let accion = null;
let aviso = null;

const PALABRAS_MENU = ['hola', 'menu', 'menú', 'inicio', 'buenas', 'buenos dias',
  'buenos días', 'buenas tardes', 'buenas noches'];

// Link/QR por profesional: saludo + más palabras ("Hola Santos").
// La base decide si alguna palabra es el nombre de una profesional.
const saludoConNombre = msg.tipo === 'texto'
  && !PALABRAS_MENU.includes(textoPlano)
  && /^(hola|buenas|buenos)\b/.test(textoPlano)
  && textoPlano.split(/\s+/).length >= 2;

// Qué pregunta repetir si el cliente responde algo que no corresponde
const REPETIR = {
  inicio: 'menu',
  autorizacion: 'pedir_autorizacion',
  menu: 'menu',
  categoria: 'listar_servicios',
  servicio: 'listar_servicios',
  profesional: 'listar_profesionales',
  dia: 'listar_dias',
  franja: 'pedir_franja',
  hora: 'listar_horas',
  confirmar: 'resumen',
  cita: 'mis_citas',
  cita_opcion: 'opciones_cita',
  cancelar: 'confirmar_cancelacion',
};

// 1) Sin autorización de datos: solo puede aceptar o no
//    Si llegó por el link de una profesional, se busca ya y se conserva para después de aceptar
if (!ctx.autorizo_datos) {
  if (id === 'auth_si') { datos = datos.profesional_fijo ? datos : {}; accion = 'registrar'; }
  else if (id === 'auth_no') { datos = {}; accion = 'sin_autorizacion'; }
  else if (saludoConNombre) { datos = { modo: 'agendar', texto_link: msg.texto }; accion = 'autorizacion_link'; }
  else accion = 'pedir_autorizacion';
}
// 2) Botones del recordatorio (sirven en cualquier paso)
else if (id.startsWith('rec_ok:')) {
  datos = { cita_id: id.split(':')[1] };
  accion = 'confirmar_asistencia';
}
else if (id.startsWith('rec_cancel:')) {
  datos = { cita_id: id.split(':')[1] };
  accion = 'confirmar_cancelacion';
}
// 3) Botones de seguimiento (sirven en cualquier paso)
//    seg_cont:<servicio>|<profesional|any>|<nombre servicio>  → abandono
//    seg_reprog:<servicio>|<profesional>|<nombre servicio>    → cancelada / no asistió
else if (id.startsWith('seg_cont:') || id.startsWith('seg_reprog:')) {
  const [srv, pro, srvNombre] = id.slice(id.indexOf(':') + 1).split('|');
  if (srv) {
    datos = {
      modo: 'agendar',
      servicio_id: srv,
      profesional_id: pro && pro !== 'any' ? pro : null,
      ...(srvNombre ? { servicio_nombre: srvNombre } : {}),
    };
    accion = 'listar_dias';
  } else {
    datos = { modo: 'agendar' };
    accion = 'listar_servicios';
  }
  aviso = id.startsWith('seg_cont:') ? '¡Listo! Retomemos tu cita 🙌' : 'Busquemos una nueva fecha 📅';
}
else if (id === 'seg_no') {
  datos = {};
  accion = 'seg_no';
}
// 4) Link/QR por profesional: busca a la profesional y muestra solo sus servicios
//    (si no hay coincidencia, Construir respuesta muestra el menú)
else if (saludoConNombre) {
  datos = { modo: 'agendar', texto_link: msg.texto };
  accion = 'link_profesional';
}
// 5) Saludo o "menú" escrito: vuelve al menú
else if (msg.tipo === 'texto' && PALABRAS_MENU.includes(textoPlano)) {
  datos = {};
  accion = 'menu';
}
// 6) Máquina de estados
else {
  switch (ctx.paso) {
    case 'menu':
      if (id === 'menu_agendar') { datos = { modo: 'agendar' }; accion = 'listar_servicios'; }
      else if (id === 'menu_citas') { datos = {}; accion = 'mis_citas'; }
      else if (id === 'menu_humano') accion = 'humano';
      // Botones que se muestran después de aceptar datos cuando llegó por el link
      else if (id === 'link_si' && datos.texto_link) accion = 'link_profesional';
      else if (id === 'menu_ver') { datos = {}; accion = 'menu'; }
      break;

    case 'categoria':
      // Más de 10 servicios: primero se elige la categoría
      if (id.startsWith('cat:')) {
        datos.categoria = id.slice(4);
        accion = 'listar_servicios';
      }
      break;

    case 'servicio':
      if (id === 'cat:*') {
        // "Otras categorías": vuelve a la lista de categorías
        delete datos.categoria;
        accion = 'listar_servicios';
      } else if (id.startsWith('srv:')) {
        datos.servicio_id = id.slice(4);
        datos.servicio_nombre = msg.texto;
        // Si llegó por el link de una profesional, ya está elegida: salta a los días
        accion = datos.profesional_fijo ? 'listar_dias' : 'listar_profesionales';
      }
      break;

    case 'profesional':
      if (id.startsWith('pro:')) {
        const p = id.slice(4);
        datos.profesional_id = p === 'any' ? null : p;
        datos.profesional_nombre = p === 'any' ? null : msg.texto;
        accion = 'listar_dias';
      }
      break;

    case 'dia':
      if (id.startsWith('dia:')) {
        datos.fecha = id.slice(4);
        datos.fecha_texto = msg.texto;
        const ahora = DateTime.now().setZone(tz);
        if (datos.fecha === ahora.toISODate() && ahora.hour >= 16) {
          // Hoy y ya pasaron las 4 p. m.: solo queda la tarde
          datos.franja = 'tarde';
          accion = 'listar_horas';
          aviso = 'Para hoy quedan horas en la tarde 🌇';
        } else {
          accion = 'pedir_franja';
        }
      }
      break;

    case 'franja':
      if (id.startsWith('fr:')) {
        datos.franja = id.slice(3);
        accion = 'listar_horas';
      }
      break;

    case 'hora':
      if (id.startsWith('hora:')) {
        datos.inicio = id.slice(5);
        datos.hora_texto = msg.texto;
        accion = 'resumen';
      }
      break;

    case 'confirmar':
      if (id === 'conf_si') accion = datos.modo === 'reprogramar' ? 'reprogramar_cita' : 'crear_cita';
      else if (id === 'conf_cambiar') accion = 'listar_dias';
      break;

    case 'cita':
      if (id.startsWith('cita:')) {
        const [citaId, servicioId, profesionalId] = id.slice(5).split('|');
        datos = { cita_id: citaId, servicio_id: servicioId, profesional_id: profesionalId, cita_texto: msg.texto };
        accion = 'opciones_cita';
      }
      break;

    case 'cita_opcion':
      if (id === 'cita_reprog') { datos.modo = 'reprogramar'; accion = 'listar_dias'; }
      else if (id === 'cita_cancel') accion = 'confirmar_cancelacion';
      else if (id === 'volver') { datos = {}; accion = 'menu'; }
      break;

    case 'cancelar':
      if (id === 'cancel_si') accion = 'cancelar_cita';
      else if (id === 'cancel_no') { datos = {}; accion = 'menu'; }
      break;

    default:
      datos = {};
      accion = 'menu';
  }

  if (!accion) {
    // Si llegó por el link, repite solo los servicios de esa profesional
    accion = ctx.paso === 'servicio' && datos.profesional_fijo && datos.texto_link
      ? 'link_profesional'
      : (REPETIR[ctx.paso] ?? 'menu');
    if (audio && audio.motivo === 'largo') {
      aviso = 'Tu audio es muy largo 🙏 Envíame uno de menos de 1 minuto o elige una opción 👇';
    } else if (audio) {
      aviso = 'No te entendí bien el audio 🙏 Elige una de las opciones 👇';
    } else {
      aviso = 'Por favor elige una de las opciones 👇';
    }
  }
}

// Qué función de Supabase necesita cada acción (null = ninguna)
const RPC = {
  registrar:            ['bot_registrar_cliente',    { p_telefono: tel, p_nombre: msg.nombre_perfil, p_acepta_datos: true }],
  listar_servicios:     ['bot_servicios',            { p_categoria: datos.categoria ?? null }],
  link_profesional:     ['bot_servicios_profesional', { p_texto: datos.texto_link ?? msg.texto }],
  autorizacion_link:    ['bot_servicios_profesional', { p_texto: datos.texto_link }],
  listar_profesionales: ['bot_profesionales',        { p_servicio: datos.servicio_id }],
  listar_dias:          ['bot_dias_disponibles',     { p_servicio: datos.servicio_id, p_profesional: datos.profesional_id ?? null }],
  listar_horas:         ['bot_horas',                { p_servicio: datos.servicio_id, p_fecha: datos.fecha, p_franja: datos.franja, p_profesional: datos.profesional_id ?? null }],
  crear_cita:           ['bot_crear_cita',           { p_telefono: tel, p_servicio: datos.servicio_id, p_inicio: datos.inicio, p_profesional: datos.profesional_id ?? null }],
  reprogramar_cita:     ['bot_reprogramar_cita',     { p_telefono: tel, p_cita: datos.cita_id, p_nuevo_inicio: datos.inicio, p_profesional: datos.profesional_id ?? null }],
  mis_citas:            ['bot_mis_citas',            { p_telefono: tel }],
  cancelar_cita:        ['bot_cancelar_cita',        { p_telefono: tel, p_cita: datos.cita_id }],
  confirmar_asistencia: ['bot_confirmar_asistencia', { p_telefono: tel, p_cita: datos.cita_id }],
  humano:               ['bot_pausar',               { p_telefono: tel, p_pausado: true }],
};

const [rpc, extra] = RPC[accion] ?? [null, null];

return [{
  json: {
    accion,
    aviso,
    datos,
    rpc,
    body: rpc ? { p_phone_number_id: phone, ...extra } : null,
    phone_number_id: phone,
    telefono: tel,
  },
}];

// CONSTRUIR RESPUESTA: arma los mensajes de WhatsApp según la acción
// y el resultado de Supabase. Define el siguiente paso de la conversación.
const r   = $('Router').first().json;
const ctx = $('Contexto').first().json;
const tz  = ctx.zona_horaria || 'America/Bogota';
const tel = r.telefono;
const d   = { ...(r.datos ?? {}) };
delete d.opciones; // se recalculan al final con lo que se envía ahora

// ---------- Resultado de Supabase (solo si se llamó) ----------
const http = $input.first().json;
const huboHttp = http.statusCode !== undefined;
let cuerpo = http.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }
const ok = huboHttp && http.statusCode < 300;
const filas = ok ? (Array.isArray(cuerpo) ? cuerpo : [cuerpo]).filter(x => x !== null && x !== undefined) : [];
const error = huboHttp && !ok ? (cuerpo?.message ?? 'ERROR') : null;

// ---------- Utilidades ----------
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);
const dt = (iso) => DateTime.fromISO(iso, { zone: tz }).setLocale('es');
const fmtFecha = (iso) => cap(dt(iso).toFormat("cccc d 'de' LLLL"));
const fmtHora = (iso) => dt(iso).toFormat('h:mm a');
const pesos = (n) => '$' + Number(n).toLocaleString('es-CO', { maximumFractionDigits: 0 });
const conAviso = (t) => (r.aviso ? `${r.aviso}\n\n${t}` : t);

const nombre = ctx.cliente_nombre || $('Normalizar').first().json.nombre_perfil || '';
const saludo = nombre ? ` ${nombre.split(' ')[0]}` : '';

// ---------- Textos según el tipo de negocio (salones.tipo) ----------
// 'estetica' deja los mensajes exactamente como estaban.
const T = {
  estetica: {
    lugar: 'salón',
    icoServicio: '💅',
    icoPro: '👩',
    preguntaPro: '¿Con quién quieres tu cita? 👩',
    botonPro: 'Ver profesionales',
    cualquieraDesc: 'La primera con cupo',
    mismaPro: 'La misma profesional',
    primeraDisp: 'La primera disponible',
    despedida: '¡Te esperamos! 💖',
    notaDatos: '',
  },
  odontologia: {
    lugar: 'consultorio',
    icoServicio: '🦷',
    icoPro: '🧑‍⚕️',
    preguntaPro: '¿Con qué odontólogo(a) quieres tu cita? 🧑‍⚕️',
    botonPro: 'Ver odontólogos',
    cualquieraDesc: 'Quien tenga cupo primero',
    mismaPro: 'El mismo odontólogo(a)',
    primeraDisp: 'Quien tenga cupo primero',
    despedida: '¡Te esperamos! 😊',
    notaDatos: ' No te pediremos información sobre tu salud.',
  },
}[ctx.salon_tipo === 'odontologia' ? 'odontologia' : 'estetica'];

// ---------- Formatos de WhatsApp ----------
const texto = (body) => ({ type: 'text', text: { body } });

const botones = (body, opciones) => ({
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: body },
    action: {
      buttons: opciones.map(([id, title]) => ({ type: 'reply', reply: { id, title: title.slice(0, 20) } })),
    },
  },
});

const lista = (body, boton, items) => ({
  type: 'interactive',
  interactive: {
    type: 'list',
    body: { text: body },
    action: {
      button: boton.slice(0, 20),
      sections: [{
        title: 'Opciones',
        rows: items.slice(0, 10).map(f => ({
          id: f.id,
          title: f.title.slice(0, 24),
          ...(f.description ? { description: f.description.slice(0, 72) } : {}),
        })),
      }],
    },
  },
});

const OPC_MENU = [['menu_agendar', 'Agendar cita'], ['menu_citas', 'Mis citas'], ['menu_humano', 'Hablar con alguien']];

// Franjas: [id, texto del botón, hora en que termina]
const FRANJAS = [['fr:manana', 'Mañana ☀️', 12], ['fr:mediodia', 'Mediodía 🌤️', 16], ['fr:tarde', 'Tarde 🌇', 24]];
const NOMBRE_FRANJA = { manana: 'mañana', mediodia: 'mediodía', tarde: 'tarde' };
// Si el día es hoy, oculta las franjas que ya terminaron
const opcFranja = (fecha) => {
  const ahora = DateTime.now().setZone(tz);
  const esHoy = fecha === ahora.toISODate();
  return FRANJAS.filter(([, , fin]) => !esHoy || ahora.hour < fin).map(([id, t]) => [id, t]);
};

const ERROR_GENERICO = 'Tuvimos un problema técnico 🙏 Intenta de nuevo en unos minutos escribiendo *Hola*.';

// Acciones que interpretan el error ellas mismas
const MANEJAN_ERROR = ['crear_cita', 'reprogramar_cita', 'cancelar_cita', 'confirmar_asistencia', 'autorizacion_link'];

let mensajes = [];   // para el cliente
let avisos = [];     // para otros números (ej. el salón)
let paso = 'inicio';
let datos = {};

if (huboHttp && !ok && !MANEJAN_ERROR.includes(r.accion)) {
  mensajes.push(texto(ERROR_GENERICO));
} else {
  switch (r.accion) {

    case 'autorizacion_link':
      // Llegó por el link de una profesional y aún no autoriza datos: se guarda la profesional
      if (filas.length) {
        d.profesional_id = filas[0].profesional_id;
        d.profesional_nombre = filas[0].profesional_nombre;
        d.profesional_fijo = true;
      }
      // sigue igual que pedir_autorizacion
    case 'pedir_autorizacion':
      mensajes.push(botones(conAviso(
        `¡Hola${saludo}! 👋 Bienvenido(a) a *${ctx.salon_nombre}*.\n\n` +
        `Para agendar por este medio necesitamos tu autorización para tratar tus datos ` +
        `(nombre y teléfono) solo para gestionar tus citas y enviarte recordatorios, ` +
        `según la Ley 1581 de 2012.${T.notaDatos}\n\n¿Nos autorizas?`),
        [['auth_si', 'Acepto'], ['auth_no', 'No acepto']]));
      paso = 'autorizacion';
      if (d.profesional_fijo) datos = d; // conserva la profesional del link
      break;

    case 'sin_autorizacion':
      mensajes.push(texto('Entendido. Sin tu autorización no podemos agendar por este medio.\n\nSi cambias de opinión, escríbenos *Hola*.'));
      break;

    case 'registrar':
      if (d.profesional_fijo) {
        const primer = d.profesional_nombre.split(' ')[0];
        mensajes.push(botones(`¡Gracias${saludo}! ✅\n\n¿Agendamos con *${primer}*?`,
          [['link_si', `Agendar con ${primer}`], ['menu_ver', 'Ver menú']]));
        paso = 'menu'; datos = d;
      } else {
        mensajes.push(botones(`¡Gracias${saludo}! ✅\n\n¿Qué quieres hacer?`, OPC_MENU));
        paso = 'menu';
      }
      break;

    case 'menu':
      mensajes.push(botones(conAviso(`¡Hola${saludo}! ¿Qué quieres hacer?`), OPC_MENU));
      paso = 'menu';
      break;

    case 'listar_servicios':
      if (!filas.length) {
        mensajes.push(texto('Por ahora no hay servicios disponibles. Escribe *Hola* para volver al menú.'));
      } else if (filas[0].tipo === 'categoria') {
        // Más de 10 servicios: primero las categorías
        delete d.categoria;
        mensajes.push(lista(conAviso(`¿Qué tipo de servicio buscas? ${T.icoServicio}`), 'Ver categorías',
          filas.map(c => ({ id: `cat:${c.nombre}`, title: c.nombre, description: `${c.cantidad} ${c.cantidad === 1 ? 'servicio' : 'servicios'}` }))));
        paso = 'categoria'; datos = d;
      } else {
        const filasSrv = filas.map(s => ({ id: `srv:${s.servicio_id}`, title: s.nombre, description: `${s.duracion_min} min · ${pesos(s.precio)}` }));
        // Dentro de una categoría: máximo 9 servicios + "Otras categorías"
        const items = d.categoria
          ? [...filasSrv.slice(0, 9), { id: 'cat:*', title: '⬅️ Otras categorías' }]
          : filasSrv;
        const titulo = d.categoria ? `*${d.categoria}*\n\n¿Qué servicio quieres? ${T.icoServicio}` : `¿Qué servicio quieres? ${T.icoServicio}`;
        mensajes.push(lista(conAviso(titulo), 'Ver servicios', items));
        paso = 'servicio'; datos = d;
      }
      break;

    case 'link_profesional':
      if (!filas.length) {
        // Ninguna profesional coincide: menú normal
        mensajes.push(botones(`¡Hola${saludo}! ¿Qué quieres hacer?`, OPC_MENU));
        paso = 'menu';
      } else {
        const pro = filas[0];
        d.profesional_id = pro.profesional_id;
        d.profesional_nombre = pro.profesional_nombre;
        d.profesional_fijo = true;
        mensajes.push(lista(conAviso(
          `¡Hola${saludo}! 👋 Vas a agendar con *${pro.profesional_nombre.split(' ')[0]}*.\n\n¿Qué servicio quieres? ${T.icoServicio}`),
          'Ver servicios',
          filas.map(s => ({ id: `srv:${s.servicio_id}`, title: s.nombre, description: `${s.duracion_min} min · ${pesos(s.precio)}` }))));
        paso = 'servicio'; datos = d;
      }
      break;

    case 'listar_profesionales':
      mensajes.push(lista(conAviso(T.preguntaPro), T.botonPro, [
        { id: 'pro:any', title: 'Cualquiera disponible', description: T.cualquieraDesc },
        ...filas.map(p => ({ id: `pro:${p.profesional_id}`, title: p.nombre })),
      ]));
      paso = 'profesional'; datos = d;
      break;

    case 'listar_dias':
      if (!filas.length) {
        mensajes.push(botones(`😕 No hay cupos en los próximos días${d.profesional_nombre ? ' con ' + d.profesional_nombre : ''}.\n\n¿Qué quieres hacer?`, OPC_MENU));
        paso = 'menu';
      } else {
        const hoy = DateTime.now().setZone(tz).startOf('day');
        mensajes.push(lista(conAviso('¿Qué día te queda bien? 📅'), 'Ver días',
          filas.map(f => {
            const dia = dt(f.fecha);
            const diff = Math.round(dia.startOf('day').diff(hoy, 'days').days);
            const etiqueta = diff === 0 ? 'Hoy · ' : diff === 1 ? 'Mañana · ' : '';
            return { id: `dia:${f.fecha}`, title: cap(dia.toFormat('cccc d')), description: etiqueta + dia.toFormat('LLLL') };
          })));
        delete d.inicio;
        paso = 'dia'; datos = d;
      }
      break;

    case 'pedir_franja':
      mensajes.push(botones(conAviso(`¿Qué franja prefieres para el *${d.fecha_texto}*?`), opcFranja(d.fecha)));
      paso = 'franja'; datos = d;
      break;

    case 'listar_horas':
      if (!filas.length) {
        const otras = opcFranja(d.fecha).filter(([fid]) => fid !== `fr:${d.franja}`);
        if (otras.length) {
          mensajes.push(botones(`😕 No quedan horas libres en la ${NOMBRE_FRANJA[d.franja] ?? 'franja'} del *${d.fecha_texto}*.\n\n¿Probamos otra franja?`, otras));
          paso = 'franja';
        } else {
          mensajes.push(botones(`😕 No quedan horas libres el *${d.fecha_texto}*.\n\n¿Qué quieres hacer?`, OPC_MENU));
          paso = 'menu';
        }
      } else {
        mensajes.push(lista(conAviso('¿A qué hora? 🕐'), 'Ver horas',
          filas.map(f => ({ id: `hora:${f.inicio}`, title: fmtHora(f.inicio) }))));
        paso = 'hora';
      }
      datos = d;
      break;

    case 'resumen': {
      const titulo = d.modo === 'reprogramar' ? '🔄 *Nueva fecha para tu cita*' : '📋 *Resumen de tu cita*';
      const quien = d.profesional_nombre ?? (d.profesional_id ? T.mismaPro : T.primeraDisp);
      mensajes.push(botones(conAviso(
        `${titulo}\n\n` +
        (d.servicio_nombre ? `${T.icoServicio} ${d.servicio_nombre}\n` : '') +
        `${T.icoPro} ${quien}\n📅 ${fmtFecha(d.inicio)}\n🕐 ${fmtHora(d.inicio)}\n\n¿Confirmamos?`),
        [['conf_si', 'Confirmar ✅'], ['conf_cambiar', 'Cambiar fecha']]));
      paso = 'confirmar'; datos = d;
      break;
    }

    case 'crear_cita':
    case 'reprogramar_cita':
      if (ok && filas[0]) {
        const c = filas[0];
        const titulo = r.accion === 'crear_cita' ? '✅ *¡Cita confirmada!*' : '✅ *¡Cita reprogramada!*';
        // Menos de 24 h: no prometer un recordatorio "un día antes"
        const horasFaltan = dt(c.inicio).diff(DateTime.now().setZone(tz), 'hours').hours;
        const cierre = horasFaltan < 24
          ? `${T.despedida} Escribe *Hola* si necesitas algo más.`
          : 'Te enviaremos un recordatorio un día antes. Escribe *Hola* si necesitas algo más.';
        mensajes.push(texto(
          `${titulo}\n\n${T.icoServicio} ${c.servicio}\n${T.icoPro} Con ${c.profesional}\n📅 ${fmtFecha(c.inicio)}\n` +
          `🕐 ${fmtHora(c.inicio)}\n💰 ${pesos(c.precio)}\n📍 ${ctx.salon_nombre}\n\n${cierre}`));
      } else if (error === 'HORARIO_NO_DISPONIBLE') {
        delete d.inicio;
        mensajes.push(botones(`😕 Esa hora se acaba de ocupar.\n\n¿Qué franja prefieres para el *${d.fecha_texto}*?`, opcFranja(d.fecha)));
        paso = 'franja'; datos = d;
      } else {
        mensajes.push(texto(ERROR_GENERICO));
      }
      break;

    case 'mis_citas':
      if (!filas.length) {
        mensajes.push(botones('No tienes citas próximas 📭\n\n¿Qué quieres hacer?', OPC_MENU));
        paso = 'menu';
      } else {
        mensajes.push(lista(conAviso('Estas son tus próximas citas. Elige una para reprogramar o cancelar 👇'), 'Ver citas',
          filas.map(c => ({
            id: `cita:${c.cita_id}|${c.servicio_id}|${c.profesional_id}`,
            title: cap(dt(c.inicio).toFormat('ccc d LLL, h:mm a')),
            description: `${c.servicio} con ${c.profesional}`,
          }))));
        paso = 'cita';
      }
      break;

    case 'opciones_cita':
      mensajes.push(botones(conAviso(`Tu cita: *${d.cita_texto}*\n\n¿Qué quieres hacer?`),
        [['cita_reprog', 'Reprogramar'], ['cita_cancel', 'Cancelar cita'], ['volver', 'Volver']]));
      paso = 'cita_opcion'; datos = d;
      break;

    case 'confirmar_cancelacion':
      mensajes.push(botones(conAviso(`¿Seguro que quieres cancelar tu cita${d.cita_texto ? ' del *' + d.cita_texto + '*' : ''}?`),
        [['cancel_si', 'Sí, cancelar'], ['cancel_no', 'No, mantenerla']]));
      paso = 'cancelar'; datos = d;
      break;

    case 'cancelar_cita':
      mensajes.push(texto(ok
        ? '✅ Tu cita fue cancelada.\n\nEscribe *Hola* si quieres agendar otra.'
        : 'No encontramos esa cita o ya no se puede cancelar. Escribe *Hola* para volver al menú.'));
      break;

    case 'confirmar_asistencia':
      mensajes.push(texto(ok
        ? '¡Gracias por confirmar! ✅ Te esperamos.'
        : 'No encontramos esa cita o ya pasó. Escribe *Hola* para volver al menú.'));
      break;

    case 'seg_no':
      mensajes.push(texto('Listo 👍 Cuando quieras agendar, escríbenos *Hola*.'));
      break;

    case 'humano':
      mensajes.push(texto(`Listo 🙌 Una persona del ${T.lugar} te escribirá por aquí en breve.`));
      if (ctx.telefono_notificaciones) {
        // Plantilla aprobada: funciona aunque el dueño no haya escrito en 24 h
        avisos.push({
          to: ctx.telefono_notificaciones,
          payload: {
            type: 'template',
            template: {
              name: 'aviso_humano',
              language: { code: 'es' },
              components: [{
                type: 'body',
                parameters: [
                  { type: 'text', text: ctx.salon_nombre },       // {{1}}
                  { type: 'text', text: nombre || 'sin nombre' }, // {{2}}
                  { type: 'text', text: tel },                    // {{3}}
                ],
              }],
            },
          },
        });
      }
      break;

    default:
      mensajes.push(botones(`¿Qué quieres hacer?`, OPC_MENU));
      paso = 'menu';
  }
}

// ---------- Guardar las opciones mostradas (para interpretar audios) ----------
const opcionesDe = (p) => {
  const i = p?.interactive;
  if (!i) return [];
  if (i.type === 'button') return i.action.buttons.map(b => ({ id: b.reply.id, title: b.reply.title }));
  if (i.type === 'list') return i.action.sections.flatMap(s => s.rows.map(f => ({
    id: f.id, title: f.title, ...(f.description ? { description: f.description } : {}),
  })));
  return [];
};
const opciones = opcionesDe(mensajes[mensajes.length - 1]);
if (opciones.length) datos = { ...datos, opciones };

// ---------- Salida: un item por mensaje ----------
const item = (to, payload) => ({
  json: {
    phone_number_id: r.phone_number_id,
    to,
    payload: { messaging_product: 'whatsapp', to, ...payload },
    telefono_cliente: tel,
    paso_nuevo: paso,
    datos_nuevos: datos,
  },
});

return [
  ...mensajes.map(p => item(tel, p)),
  ...avisos.map(a => item(a.to, a.payload)),
];

