// INTERPRETAR AUDIO: convierte el número elegido por el modelo en una respuesta
// igual a la de un botón. Valida que el número exista en las opciones mostradas.
const ctx = $('Contexto').first().json;
const opciones = ctx.datos?.opciones ?? [];

let respuesta_id = null;
let texto = '';
let motivo = null;
let transcripcion = '';

if (!$('Descargar audio').isExecuted) {
  // Salió por la rama "audio largo"
  motivo = 'largo';
} else {
  transcripcion = $('Transcribir').isExecuted ? ($('Transcribir').first().json.text ?? '') : '';
  let numero = 0;
  try {
    const raw = $('Elegir opción').first().json.choices?.[0]?.message?.content ?? '';
    numero = Number(JSON.parse(raw).opcion) || 0;
  } catch (e) {}
  const op = numero >= 1 && numero <= opciones.length ? opciones[numero - 1] : null;
  if (op) {
    respuesta_id = op.id;
    texto = op.title;
  } else {
    motivo = 'no_entendido';
  }
}

return [{ json: { respuesta_id, texto, motivo, transcripcion } }];
